CREATE TABLE `settings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `api_key` text COLLATE utf8mb4_unicode_ci,
  `openai_api_key` text COLLATE utf8mb4_unicode_ci,
  `model` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'gemini-2.5-flash',
  `tone` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Professional',
  `custom_prompt` longtext COLLATE utf8mb4_unicode_ci,
  `target_audience` text COLLATE utf8mb4_unicode_ci,
  `brand` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `word_count_mode` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'total',
  `word_count_divisor` int NOT NULL DEFAULT '10',
  `target_word_count` int NOT NULL DEFAULT '2500',
  `target_language` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'English',
  `cta_link` text COLLATE utf8mb4_unicode_ci,
  `wp_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wp_username` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wp_app_password` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
